import{_ as m,l as i,o as e,c as s,v as h,p as n,x as l,d as t,i as d,S as p,b as o}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"MoE 的通信-计算比","description":"","frontmatter":{"title":"MoE 的通信-计算比","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/moe-comm-compute-ratio.md","filePath":"llm/moe-comm-compute-ratio.md","lastUpdated":1789023840000}'),E={name:"llm/moe-comm-compute-ratio.md"};function c(A,a,M,k,u,B){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=h('<h1 id="moe-的通信-计算比" tabindex="-1">MoE 的通信-计算比 <a class="header-anchor" href="#moe-的通信-计算比" aria-label="Permalink to &quot;MoE 的通信-计算比&quot;">​</a></h1><div class="epigraph"><p>稀疏省的是专家内部 GEMM；All-to-All 把隐状态按路由搬动，带宽不够时 MoE 比稠密更慢。</p><footer>—— Lepikhin et al., GShard, 2020；实现侧亦见 MegaBlocks 对分组 GEMM 与通信重叠的处理</footer></div><p><a href="/llm/hierarchical-moe">层次 MoE</a>、<a href="/llm/node-limited-routing">节点受限</a>、<a href="/llm/switch-transformer">Switch</a> 都改扇出，但课序还没有把「何时划算」写成一条比。本课补通信-计算比：一次 MoE 层里，跨设备字节对专家 FLOPs 的比值，以及 \\(d\\)、\\(k\\)、\\(M\\)、专家宽度如何进公式。后课抖动是质量问题；本课是能不能跑满硬件。主干 <a href="/llm/megablocks">MegaBlocks</a> 给分组 GEMM，不重复其实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>稠密 FFN 的通信主要是张量并行切 \\(d\\)，有成熟重叠。MoE 多一次按 token 的动态 All-to-All：体积 \\(\\approx \\mathrm{batch}\\times n \\times k \\times d \\times \\mathrm{bytes}\\) 量级（还要算回程）。计算 \\(\\approx \\mathrm{batch}\\times n \\times k \\times \\mathrm{FLOPs}(E)\\)。专家很窄、 \\(d\\) 很大、\\(k\\) 不小时，比值恶化，机器在等网。缺口是设计时先算这条比，再决定 \\(N\\)、宽度、层次，而不是先定 \\(N=64\\) 再发现机群跑不满。</p><p><span class="marginnote">计算里不要漏掉未选专家：它们 FLOPs 为零，但若权重仍要在设备间同步（优化器状态），那是另一次通信账，属数据并行 / 专家并行的放置，本课主账是前向 All-to-All。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>粗公式：令每 token 激活 \\(k\\) 个专家，每专家 FLOPs 为 \\(c\\cdot d\\cdot w\\)（\\(w\\) 为中间宽），每 token 通信字节为 \\(2k d b\\)（去回）。比 \\(\\rho=\\mathrm{comm}/\\mathrm{comp}\\propto (k d)/(k d w)=1/w\\)。<strong>专家越宽，\\(\\rho\\) 越好</strong>；切细粒度窄专家，\\(\\rho\\) 变差。\\(k\\) 在分子分母同阶，对 \\(\\rho\\) 影响弱于 \\(w\\)，但 \\(k\\) 增大会增绝对通信，延迟仍涨。节点受限把有效对端从 \\(P\\) 台收到 \\(M\\)，延迟与争用下降，体积若仍 \\(k\\) 份向量则字节相近，但拓扑更局部。</p><p>重叠：计算当前层注意力时发上一层 MoE 的通信，或分组 GEMM 与通信流水。\\(\\rho\\) 接近 1 时重叠也救不了。设计目标是让专家 GEMM 明显长于 All-to-All 的传输时间。</p><h3 id="与张量并行叠" tabindex="-1">与张量并行叠 <a class="header-anchor" href="#与张量并行叠" aria-label="Permalink to &quot;与张量并行叠&quot;">​</a></h3><p>注意力仍 TP，MoE 常 EP（专家并行）。两条通信域争用同一张网。报 \\(\\rho\\) 应在真实并行策略下测，而不是单机公式。层次 MoE 若组=EP 组，第一跳便宜。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>细粒度专家在质量与粒度律上可能赢，在 \\(\\rho\\) 上输。这就是为何共享专家（本地常开、无 All-to-All）能改善系统：一部分 FLOPs 变回稠密本地 GEMM，拉低平均 \\(\\rho\\)。哈希与节点受限改善的是争用与跳数，不一定减少字节。Soft MoE 对所有专家通信，\\(\\rho\\) 最差。</p><p>容量因子过小导致 drop，表面上通信变少（丢了 token），质量掉，不是合法降 \\(\\rho\\) 的方法。把专家复制到每台机器可以去掉 All-to-All，但内存按 \\(N\\) 倍涨，只适合小 \\(N\\)。\\(\\rho\\) 恶化时先考虑加 \\(w\\)、加共享专家、收 \\(M\\)，再考虑复制。</p><p><span class="marginnote">推理 batch 小，\\(n\\) 的有效值小，All-to-All 启动开销主导，\\(\\rho\\) 比训练更差。服务 MoE 要用足够的 token 聚合，或接受本地专家复制。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课公式忽略拓扑非均匀（机柜内外差一个数量级）。真实选型要按链路测。下一课路由抖动会让通信体积随步变化，使 \\(\\rho\\) 的方差变大，缓冲更难。粒度律课会与 \\(\\rho\\) 对质：质量要更细的专家，系统要更宽的专家，折中点不是纯损失最小点。</p>',17)),(e(),n(p,null,{default:l(()=>[d(r,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22k%20%E4%B8%8E%20d%22%5D%20--%3E%20Comm%5B%22All-to-All%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20W%5B%22%E4%B8%93%E5%AE%B6%E5%AE%BD%E5%BA%A6%20w%22%5D%20--%3E%20Comp%5B%22%E4%B8%93%E5%AE%B6%20GEMM%22%5D%0A%20%20Comm%20--%3E%20Rho%5B%22%E6%AF%94%20rho%22%5D%0A%20%20Comp%20--%3E%20Rho%0A%20%20M%5B%22%E8%8A%82%E7%82%B9%E5%8F%97%E9%99%90%20M%22%5D%20--%3E%20Comm%0A%20%20Shared%5B%22%E5%85%B1%E4%BA%AB%E4%B8%93%E5%AE%B6%E6%9C%AC%E5%9C%B0%E7%AE%97%22%5D%20--%3E%20Comp%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o("h2",{id:"小结",tabindex:"-1"},[t("小结 "),o("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=o("ul",null,[o("li",null,"MoE 的系统可行性由 All-to-All 字节对专家 GEMM 的比决定；专家宽度 \\(w\\) 是最敏感项。"),o("li",null,"细粒度窄专家伤 \\(\\rho\\)；共享专家、节点受限、通信重叠是补救。"),o("li",null,"\\(k\\) 对 \\(\\rho\\) 同阶相消，但仍增延迟与争用。"),o("li",null,"推理小 batch 时启动开销使情况更差。"),o("li",null,"出处：Lepikhin et al., 2020；MegaBlocks 一类实现。")],-1))])}const P=m(E,[["render",c]]);export{b as __pageData,P as default};
